_CORE_SRC = '# Diagnosis:\n# The report shows the close pairing is the other best responder, not idle or\n# the safe bot. The seat split also indicates that geography matters. The\n# champion already values denial and arrival delay, but freezes the opponent\n# for its entire planning horizon. In particular, it treats busy nodes near an\n# opponent\'s initially full base as uncontested.\n#\n# There is also a planning/execution mismatch: its greedy allocation charges\n# travel from selected sources, then discards those assignments and rematches\n# the final allocation. Intermediate-node revenue and congestion are omitted.\n#\n# This strategy makes two changes:\n# 1. Optimize actual, legal, one-hop unit trajectories with coordinate dynamic\n#    programming. Intermediate service, congestion, upkeep, recall, and the\n#    exact final horizon are all included.\n# 2. Predict an opponent deployment and hedge it against stationary positions.\n#    Prediction confidence is adjusted by observed prediction errors.\n# The exact three-turn forecast is retained. Beyond it, demand shares revert\n# toward hub shares (especially informative when first observed on turn zero).\n\nimport math\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_data = None\n        self.own_paths = None\n        self.enemy_paths = None\n        self.last_turn = None\n        self.hubs = None\n        self.bad_reports = 0\n        self.previous_enemy = None\n        self.predicted_enemy = None\n        self.pred_error = 3.0\n        self.stay_error = 3.0\n\n    def _build_map(self, graph):\n        n = int(graph["nodes"])\n        adj = [[] for _ in range(n)]\n        for u, v in graph["links"]:\n            adj[u].append(v)\n            adj[v].append(u)\n        for row in adj:\n            row.sort()\n        dist = []\n        for s in range(n):\n            d = [-1] * n\n            d[s] = 0\n            q = deque([s])\n            while q:\n                u = q.popleft()\n                for v in adj[u]:\n                    if d[v] < 0:\n                        d[v] = d[u] + 1\n                        q.append(v)\n            dist.append(d)\n        self.map_data = (n, adj, dist)\n\n    def _warm_paths(self, counts, old, horizon, consecutive):\n        n = len(counts)\n        pools = [[] for _ in range(n)]\n        if consecutive and old:\n            for _, path in old:\n                if path:\n                    source = path[0]\n                    tail = list(path[1:])\n                    if not tail:\n                        tail = [source]\n                    tail = (tail + [tail[-1]] * horizon)[:horizon]\n                    pools[source].append(tail)\n        result = []\n        # Active couriers are considered before idle couriers during each sweep.\n        for s in range(n):\n            for k in range(int(counts[s])):\n                path = pools[s][k] if k < len(pools[s]) else [s] * horizon\n                result.append((s, list(path)))\n        return result\n\n    @staticmethod\n    def _occupancy(paths, horizon, n):\n        counts = [[0] * n for _ in range(horizon)]\n        for _, path in paths:\n            for t, v in enumerate(path):\n                counts[t][v] += 1\n        return counts\n\n    def _demands(self, obs, horizon, n):\n        forecast = obs.get("orders", [])\n        if not forecast:\n            return [[0.0] * n for _ in range(horizon)]\n        base = int(obs["you"]["base"])\n        enemy_base = int(obs["rival"]["base"])\n        if self.hubs is None:\n            first = forecast[0]\n            self.hubs = [\n                0.0 if v == base or v == enemy_base else max(0.04, float(first[v]))\n                for v in range(n)\n            ]\n            total = sum(self.hubs) or 1.0\n            self.hubs = [x / total for x in self.hubs]\n\n        result = [list(map(float, row)) for row in forecast[:horizon]]\n        last = forecast[-1]\n        total = sum(last)\n        if len(forecast) > 1:\n            slope = max(0.0, (total - sum(forecast[0])) / (len(forecast) - 1))\n        else:\n            slope = 0.0\n        last_share = [max(0.0001, float(x) / max(total, 0.01)) for x in last]\n        while len(result) < horizon:\n            offset = len(result) - len(forecast) + 1\n            persistence = 0.92 ** offset\n            shares = [\n                0.0 if v == base or v == enemy_base else\n                math.exp(\n                    persistence * math.log(last_share[v])\n                    + (1.0 - persistence) * math.log(max(self.hubs[v], 0.0001))\n                )\n                for v in range(n)\n            ]\n            normalizer = sum(shares) or 1.0\n            future_total = min(125.0, total + slope * offset)\n            result.append([future_total * x / normalizer for x in shares])\n        return result\n\n    @staticmethod\n    def _marginals(demands, costs, scenarios, denial, weights):\n        # scenarios = [(probability, occupancy_by_turn), ...].\n        # The seventh and subsequent couriers have zero additional revenue,\n        # but incur the full upkeep.\n        horizon = len(demands)\n        n = len(costs)\n        table = []\n        for t in range(horizon):\n            row = []\n            for v in range(n):\n                d = demands[t][v]\n                values = [0.0] * 7\n                for probability, occupancy in scenarios:\n                    b = 4.0 * min(6, occupancy[t][v])\n                    for k in range(7):\n                        a = 4.0 * k\n                        denominator = max(a + b, d)\n                        if denominator > 0.0:\n                            values[k] += probability * (a - denial * b) * d / denominator\n                weight = weights[t]\n                gains = [\n                    weight * (values[k + 1] - values[k] - costs[v])\n                    for k in range(6)\n                ]\n                gains.append(-weight * costs[v])\n                row.append(gains)\n            table.append(row)\n        return table\n\n    def _optimize(self, paths, table, weights, base, sweeps, deadline):\n        n, adj, _ = self.map_data\n        horizon = len(table)\n        occupancy = self._occupancy(paths, horizon, n)\n        order = sorted(range(len(paths)), key=lambda j: (paths[j][0] == base, j))\n\n        for sweep in range(sweeps):\n            changed = False\n            # Reverse the second pass to reduce assignment-order bias.\n            sequence = order if sweep % 2 == 0 else list(reversed(order))\n            for j in sequence:\n                if time.perf_counter() >= deadline:\n                    return paths, occupancy\n                source, old_path = paths[j]\n                for t, v in enumerate(old_path):\n                    occupancy[t][v] -= 1\n\n                continuation = [0.0] * n\n                choices = [None] * horizon\n                for t in range(horizon - 1, -1, -1):\n                    tab = table[t]\n                    occ = occupancy[t]\n                    # Tiny persistence regularizer, not an economic substitute\n                    # for the actual movement/upkeep calculations.\n                    rewards = [\n                        tab[v][min(6, occ[v])]\n                        + (0.012 * weights[t] if v == old_path[t] else 0.0)\n                        + continuation[v]\n                        for v in range(n)\n                    ]\n                    move_penalty = 0.025 * weights[t]\n                    current = [0.0] * n\n                    choice = [0] * n\n                    for u in range(n):\n                        best = rewards[u]\n                        destination = u\n                        for v in adj[u]:\n                            value = rewards[v] - move_penalty\n                            if value > best + 1e-10:\n                                best = value\n                                destination = v\n                        current[u] = best\n                        choice[u] = destination\n                    choices[t] = choice\n                    continuation = current\n\n                position = source\n                new_path = []\n                for t in range(horizon):\n                    position = choices[t][position]\n                    new_path.append(position)\n                    occupancy[t][position] += 1\n                if new_path != old_path:\n                    changed = True\n                paths[j] = (source, new_path)\n            if not changed:\n                break\n        return paths, occupancy\n\n    def _validate(self, paths, have):\n        n, adj, _ = self.map_data\n        proposed = {}\n        for source, path in paths:\n            if path and path[0] != source:\n                destination = path[0]\n                key = (source, destination)\n                proposed[key] = proposed.get(key, 0) + 1\n\n        available = list(have)\n        action = {}\n        for (source, destination), requested in sorted(proposed.items()):\n            if not (0 <= source < n and 0 <= destination < n):\n                continue\n            if destination not in adj[source]:\n                continue\n            count = min(int(requested), int(available[source]))\n            if count > 0:\n                action.setdefault(int(source), {})[int(destination)] = int(count)\n                available[source] -= count\n        return action\n\n    def _recall(self, have, base):\n        n, adj, dist = self.map_data\n        action = {}\n        for s in range(n):\n            if s == base or have[s] <= 0:\n                continue\n            candidates = [v for v in adj[s] if dist[v][base] == dist[s][base] - 1]\n            if candidates:\n                action[int(s)] = {int(candidates[0]): int(have[s])}\n        return action\n\n    def act(self, obs):\n        start = time.perf_counter()\n        budget = max(0.0, float(TIME_BUDGET))\n        deadline = start + 0.58 * budget\n        if self.map_data is None:\n            self._build_map(obs["graph"])\n        n, adj, dist = self.map_data\n        have = list(obs["you"]["units"])\n        enemy = list(obs["rival"]["units"])\n        if not have or not sum(have):\n            return {}\n        base = int(obs["you"]["base"])\n        enemy_base = int(obs["rival"]["base"])\n        turn = int(obs.get("turn", 0))\n        remaining = max(0, 90 - turn)\n        if remaining == 0:\n            return {}\n\n        feedback = obs.get("feedback", {})\n        if not feedback.get("format_ok", True) or feedback.get("rejected", 0):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            return self._recall(have, base)\n\n        consecutive = self.last_turn is not None and turn == self.last_turn + 1\n        if consecutive and self.previous_enemy is not None:\n            stay_error = sum(abs(enemy[v] - self.previous_enemy[v]) for v in range(n))\n            if self.predicted_enemy is not None:\n                pred_error = sum(abs(enemy[v] - self.predicted_enemy[v]) for v in range(n))\n                self.pred_error = 0.8 * self.pred_error + 0.2 * pred_error\n                self.stay_error = 0.8 * self.stay_error + 0.2 * stay_error\n\n        horizon = min(14, remaining)\n        demands = self._demands(obs, horizon, n)\n        weights = [0.95 ** t for t in range(horizon)]\n        own_cost = [0.0 if v == base else 1.0 + 0.5 * dist[base][v] for v in range(n)]\n        enemy_cost = [\n            0.0 if v == enemy_base else 1.0 + 0.5 * dist[enemy_base][v]\n            for v in range(n)\n        ]\n\n        own_paths = self._warm_paths(have, self.own_paths, horizon, consecutive)\n        enemy_paths = self._warm_paths(enemy, self.enemy_paths, horizon, consecutive)\n        own_occupancy = self._occupancy(own_paths, horizon, n)\n\n        # Predict a competent, cost-aware opponent. This is deliberately a\n        # mixture model rather than assuming its next move is known.\n        opponent_table = self._marginals(\n            demands, enemy_cost, [(1.0, own_occupancy)], 0.85, weights\n        )\n        prediction_deadline = min(deadline, start + 0.22 * budget)\n        enemy_paths, predicted = self._optimize(\n            enemy_paths, opponent_table, weights, enemy_base, 2, prediction_deadline\n        )\n        confidence = 0.20 + 0.65 * (\n            (self.stay_error + 0.5) / (self.stay_error + self.pred_error + 1.0)\n        )\n        if turn == 0:\n            confidence = 0.72\n        stationary = [list(enemy) for _ in range(horizon)]\n        own_table = self._marginals(\n            demands, own_cost,\n            [(confidence, predicted), (1.0 - confidence, stationary)],\n            1.0, weights\n        )\n        own_paths, _ = self._optimize(\n            own_paths, own_table, weights, base, 5, deadline\n        )\n\n        # Every trajectory starts at a real start-of-turn courier and uses\n        # only adjacency transitions. Validate again while aggregating counts;\n        # arrivals are never added to the start-of-turn availability.\n        action = self._validate(own_paths, have)\n        self.own_paths = own_paths\n        self.enemy_paths = enemy_paths\n        self.predicted_enemy = list(predicted[0])\n        self.previous_enemy = list(enemy)\n        self.last_turn = turn\n        return action\n'
