_FALLBACK_SRC = '# Action format: "{from_node: {to_node: count, ...}}".\n# Payout: "serving_p = min(units_p at the node, SERVE_LIMIT)";\n# "capacity_p = serving_p * UNIT_CAPACITY";\n# "filled_p = capacity_p * orders / max(total_capacity, orders)".\n# Cost: "upkeep(node) = UPKEEP_BASE + UPKEEP_PER_HOP *\n# hops(your_base, node)". Units on their own base cost 0.\n#\n# Conservative fallback: only fund short trips from the exact forecast,\n# including the cost of returning home. No speculative long-term orders,\n# opponent prediction, randomness, or search is used.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 90\nUNIT_CAPACITY = 4\nSERVE_LIMIT = 6\n\n\ndef preprocess_map(graph):\n    n = int(graph["nodes"])\n    adjacency = [[] for _ in range(n)]\n    for a, b in graph["links"]:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbours in adjacency:\n        neighbours.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbour in adjacency[node]:\n                if row[neighbour] == -1:\n                    row[neighbour] = row[node] + 1\n                    queue.append(neighbour)\n        distances.append(row)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        next_hop[source][source] = source\n        for target in range(n):\n            if distances[source][target] > 0:\n                next_hop[source][target] = next(\n                    neighbour for neighbour in adjacency[source]\n                    if distances[neighbour][target]\n                    == distances[source][target] - 1\n                )\n    return adjacency, distances, next_hop\n\n\ndef filled_orders(own_units, rival_units, orders):\n    own_capacity = min(own_units, SERVE_LIMIT) * UNIT_CAPACITY\n    rival_capacity = min(rival_units, SERVE_LIMIT) * UNIT_CAPACITY\n    denominator = max(own_capacity + rival_capacity, orders)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * orders / denominator\n\n\ndef return_cost(source, base, next_hop, upkeep):\n    """All upkeep paid while taking the shortest route home, moves first."""\n    cost = 0.0\n    node = source\n    while node != base:\n        node = next_hop[node][base]\n        cost += upkeep[node]\n    return cost\n\n\ndef plan_moves(own, rival, base, forecasts, adjacency, distances, next_hop):\n    n = len(own)\n    horizon = len(forecasts)\n    upkeep = [\n        0.0 if node == base else 1.0 + 0.5 * distances[base][node]\n        for node in range(n)\n    ]\n    recall = [\n        return_cost(node, base, next_hop, upkeep)\n        for node in range(n)\n    ]\n    assigned = [0] * n\n    planned = {}\n\n    # Already deployed couriers get first claim on useful work. All units\n    # are considered from their actual start-of-turn source, never arrivals.\n    sources = sorted(\n        (node for node in range(n) if own[node] > 0),\n        key=lambda node: (node == base, distances[base][node], node),\n    )\n    for source in sources:\n        for _ in range(own[source]):\n            best_target = base\n            best_value = -recall[source]\n            best_distance = distances[source][base]\n\n            candidates = sorted(\n                range(n), key=lambda node: (distances[source][node], node)\n            )\n            for target in candidates:\n                if target == base or assigned[target] >= SERVE_LIMIT:\n                    continue\n                distance = distances[source][target]\n                # New contests are deliberately avoided. Existing couriers\n                # can stay only if their actual proportional revenue pays.\n                if rival[target] > 0 and target != source:\n                    continue\n                arrival = max(1, distance)\n                if arrival > horizon:\n                    continue\n\n                # Account for every outward journey turn, then destination\n                # upkeep through the forecast, then a complete recall.\n                value = -recall[target]\n                node = source\n                for offset in range(horizon):\n                    if node != target:\n                        node = next_hop[node][target]\n                    value -= upkeep[node]\n                    if node == target:\n                        value += (\n                            filled_orders(\n                                assigned[target] + 1,\n                                rival[target],\n                                forecasts[offset][target],\n                            )\n                            - filled_orders(\n                                assigned[target],\n                                rival[target],\n                                forecasts[offset][target],\n                            )\n                        )\n\n                # Require a clear surplus over immediately returning home.\n                # Deployments from base must additionally pay the entire\n                # round trip out of known forecast revenue.\n                margin = 0.8 if source == base else 0.25\n                if value > best_value + margin:\n                    best_target = target\n                    best_value = value\n                    best_distance = distance\n                elif (\n                    best_target != base\n                    and abs(value - best_value) < 1e-9\n                    and distance < best_distance\n                ):\n                    best_target = target\n                    best_distance = distance\n\n            assigned[best_target] += 1\n            if best_target != source:\n                destination = next_hop[source][best_target]\n                pair = (source, destination)\n                planned[pair] = planned.get(pair, 0) + 1\n\n    return planned\n\n\ndef legal_action(planned, own, adjacency):\n    """Validate against start-of-turn availability, not arriving units."""\n    available = list(own)\n    action = {}\n    n = len(own)\n    for (source, destination), requested in sorted(planned.items()):\n        source, destination = int(source), int(destination)\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if source == destination or destination not in adjacency[source]:\n            continue\n        count = int(min(max(0, requested), available[source]))\n        if count <= 0:\n            continue\n        available[source] -= count\n        if source not in action:\n            action[int(source)] = {}\n        action[int(source)][int(destination)] = int(count)\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_cache = None\n\n    def act(self, obs):\n        # No evolving tactical state: missed calls cannot invalidate a plan.\n        if self.map_cache is None:\n            self.map_cache = preprocess_map(obs["graph"])\n        adjacency, distances, next_hop = self.map_cache\n        own = obs["you"]["units"]\n        rival = obs["rival"]["units"]\n        base = int(obs["you"]["base"])\n        remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n        forecasts = obs.get("orders", [])[:min(3, remaining)]\n        if not forecasts or not own or sum(own) == 0:\n            return {}\n\n        # Fixed work: at most 24 couriers * 18 nodes * 3 forecast turns.\n        # The same conservative, validated builder is always used, including\n        # after any feedback reporting a rejected or malformed prior action.\n        planned = plan_moves(\n            own, rival, base, forecasts, adjacency, distances, next_hop\n        )\n        return legal_action(planned, own, adjacency)\n'
